let purchaseKeys=null;
const purchaseNote=s=>{document.getElementById('purchaseStatus').textContent=s;};
async function importPurchaseKey(jwk){if(!jwk||jwk.kty!=='OKP'||jwk.crv!=='Ed25519'||typeof jwk.d!=='string'||typeof jwk.x!=='string')throw new Error('Expected Ed25519 private JWK');const publicJwk={kty:'OKP',crv:'Ed25519',x:jwk.x};const privateKey=await crypto.subtle.importKey('jwk',jwk,{name:'Ed25519'},false,['sign']);const verifyKey=await crypto.subtle.importKey('jwk',publicJwk,{name:'Ed25519'},false,['verify']);const probe=new TextEncoder().encode('paragon-purchase-key-consistency-v1');const sig=await crypto.subtle.sign('Ed25519',privateKey,probe);if(!await crypto.subtle.verify('Ed25519',verifyKey,sig,probe))throw new Error('Key pair mismatch');purchaseKeys={privateKey,publicJwk};return keyFingerprint(publicJwk);}
