async function signPurchaseArtifact(payload){if(!purchaseKeys)throw new Error('Generate or import the separate purchase-record private key first');const text='paragon-private-purchase-artifact-v1'+String.fromCharCode(10)+canonical(payload);const signature=new Uint8Array(await crypto.subtle.sign('Ed25519',purchaseKeys.privateKey,new TextEncoder().encode(text)));return {format:'paragon-private-purchase-envelope/0.1',payload,integrity:{algorithm:'SHA-256',digest:await digest(payload)},authentication:{algorithm:'Ed25519',publicJwk:purchaseKeys.publicJwk,fingerprint:await keyFingerprint(purchaseKeys.publicJwk),signature:base64url(signature)},limitations:['Signature under a key, not independent source authentication.','Not a tax invoice or proof of payment.','Manual local entry; not a Shopify-issued or carrier-issued record.','No public online revocation service; check separately supplied correction notices.']};}
document.getElementById('purchaseIssue').onclick=async()=>{try{const reference=document.getElementById('purchaseRef').value.trim();if(!/^[A-Za-z0-9_-]{1,48}$/.test(reference))throw new Error('Use a non-sensitive ASCII reference, not customer or tracking information');const purchaseDate=document.getElementById('purchaseDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(purchaseDate))throw new Error('Select a purchase date');const rawAmount=document.getElementById('purchaseAmount').value;if(!/^\d{1,7}(\.\d{1,2})?$/.test(rawAmount))throw new Error('Enter a valid non-negative EUR amount with at most two decimals');const minorUnits=Math.round(Number(rawAmount)*100);if(!Number.isSafeInteger(minorUnits)||minorUnits>100000000)throw new Error('Amount out of bounds');const demo=document.getElementById('purchaseDemo').checked;const payload={format:'paragon-private-purchase-record/0.1',recordId:crypto.randomUUID(),issuedAt:new Date().toISOString(),source:demo?'synthetic_demonstration':'manual_merchant_entry_not_independently_verified',reference,purchaseDate,currency:'EUR',amountMinorUnits:minorUnits,privacy:'Private holder file; do not publish',paymentVerified:false,deliveryVerified:false,taxInvoice:false};const envelope=await signPurchaseArtifact(payload);download('paragon-PRIVATE-purchase-record.json',JSON.stringify(envelope,null,2),'application/json');purchaseNote('Signed '+(demo?'SYNTHETIC demonstration':'manually entered private')+' record created locally. Digest: '+envelope.integrity.digest+'. This does not verify a real order or payment.');}catch(e){purchaseNote('RECORD NOT CREATED: '+e.message);}};
document.getElementById('purchaseCorrect').onclick=async()=>{try{const target=document.getElementById('purchaseTarget').value.trim().toLowerCase();const disposition=document.getElementById('purchaseDisposition').value;const replacement=document.getElementById('purchaseReplacement').value.trim().toLowerCase();if(!/^[0-9a-f]{64}$/.test(target))throw new Error('Expected previous payload digest');if(!['withdrawn','superseded'].includes(disposition))throw new Error('Invalid disposition');if(disposition==='superseded'&&(!/^[0-9a-f]{64}$/.test(replacement)||target===replacement))throw new Error('A distinct replacement digest is required');const payload={format:'paragon-private-purchase-status/0.1',noticeId:crypto.randomUUID(),issuedAt:new Date().toISOString(),targetPayloadDigest:target,disposition,replacementPayloadDigest:disposition==='superseded'?replacement:null,scope:'Publisher statement only; must be checked with the original record and its independently trusted key.'};const e=await signPurchaseArtifact(payload);download('paragon-PRIVATE-purchase-status.json',JSON.stringify(e,null,2),'application/json');purchaseNote('Private signed notice created. No public registry or recipient was updated.');}catch(e){purchaseNote('NOTICE NOT CREATED: '+e.message);}};
document.getElementById('purchaseVerifyFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>65536)throw new Error('Artifact too large');const v=JSON.parse(await f.text());if(v.format!=='paragon-private-purchase-envelope/0.1'||!['paragon-private-purchase-record/0.1','paragon-private-purchase-status/0.1'].includes(v.payload?.format))throw new Error('Unsupported record');if(v.integrity?.algorithm!=='SHA-256'||await digest(v.payload)!==v.integrity.digest)throw new Error('Digest mismatch');const a=v.authentication;if(a?.algorithm!=='Ed25519')throw new Error('Unsupported signature');const fingerprint=await keyFingerprint(a.publicJwk);if(fingerprint!==a.fingerprint)throw new Error('Fingerprint mismatch');const trusted=document.getElementById('purchaseTrusted').value.trim().toLowerCase();if(trusted&&(!/^[0-9a-f]{64}$/.test(trusted)||trusted!==fingerprint))throw new Error('Invalid or unexpected trusted key');const k=await crypto.subtle.importKey('jwk',a.publicJwk,{name:'Ed25519'},false,['verify']);const message='paragon-private-purchase-artifact-v1'+String.fromCharCode(10)+canonical(v.payload);if(!await crypto.subtle.verify('Ed25519',k,unbase64url(a.signature),new TextEncoder().encode(message)))throw new Error('Invalid signature');purchaseNote('VALID integrity and signature '+(trusted?'under supplied trusted key.':'under included key only; publisher identity unestablished.')+' No verification of payment, source truth, latest status or absence of correction notices. '+JSON.stringify(v.payload,null,2));}catch(err){purchaseNote('VERIFICATION FAILED: '+err.message);}};
function byteJoin(...arrays){const length=arrays.reduce((n,a)=>n+a.length,0);const out=new Uint8Array(length);let at=0;for(const a of arrays){out.set(a,at);at+=a.length;}return out;}
function varintLEB128(n){if(!Number.isSafeInteger(n)||n<0)throw new Error('Invalid length');const bytes=[];do{const b=n%128;n=Math.floor(n/128);bytes.push(b+(n?128:0));}while(n);return new Uint8Array(bytes);}
function base32Lower(bytes){const alphabet='abcdefghijklmnopqrstuvwxyz234567';let bits=0,value=0,out='';for(const byte of bytes){value=(value<<8)|byte;bits+=8;while(bits>=5){bits-=5;out+=alphabet[(value>>>bits)&31];}value&=(1<<bits)-1;}if(bits)out+=alphabet[(value<<(5-bits))&31];return out;}
document.getElementById('carExport').onclick=async()=>{try{const c=parse();const data=new TextEncoder().encode(canonical(c.payload));const hash=new Uint8Array(await crypto.subtle.digest('SHA-256',data));const cid=byteJoin(new Uint8Array([1,0x55,0x12,0x20]),hash);const cidText='b'+base32Lower(cid);const enc=new TextEncoder();const header=byteJoin(new Uint8Array([0xa2,0x65]),enc.encode('roots'),new Uint8Array([0x81,0xd8,0x2a,0x58,cid.length+1,0]),cid,new Uint8Array([0x67]),enc.encode('version'),new Uint8Array([1]));const car=byteJoin(varintLEB128(header.length),header,varintLEB128(cid.length+data.length),cid,data);download('paragon-public-payload.car',car,'application/vnd.ipld.car');download('paragon-public-payload-cid.json',JSON.stringify({format:'paragon-raw-car-manifest/0.1',root:cidText,codec:'raw',hash:'sha2-256',payloadEncoding:'custom canonical JSON UTF-8',publicPayloadOnly:true,published:false,pinned:false,meaning:'Single-block CARv1 export; not availability or publisher authentication.'},null,2),'application/json');document.getElementById('carStatus').textContent='Generated local single-block CARv1. CID: '+cidText+'. Not uploaded or pinned. Export code has not been interoperability-tested.';}catch(e){document.getElementById('carStatus').textContent='EXPORT FAILED: '+e.message;}};

restore();
