function publicSummaryPdf(){const lines=["PARAGON | PUBLIC EVIDENCE SUMMARY","Prepared 19 November 2026. Historical source summary.","Company: PARAGON ELITE GROUP SINGLE MEMBER P.C.","GEMI: 182550901000 | EUID: ELGEMI.182550901000","Company particulars: owner-supplied historical documents.","Issuer authenticity and current status not independently verified.","","Recorded deliveries include destinations such as Greece, Germany,","France, Spain, Sweden, Poland, Norway, the United Kingdom, Brazil,","Canada and New Zealand. No customer or order totals are disclosed.","","Selected historical transit examples recorded in the merchant store:","Germany: approximately 1-2 calendar days; France: approximately 2-3.","Brazil and Canada: approximately 7-8 calendar days.","Intervals run from recorded transit start to recorded delivery.","Examples only, not typical averages or future delivery guarantees.","No usable transit-start timestamp was available for New Zealand.","","Shipment source: complete non-cancelled order read, 19 November 2026.","This summary is not a Shopify-issued or DHL-issued attestation.","Signatures verify integrity under a key, not truth of source claims.","OpenTimestamps can prove existence before a time, not business quality.","No completed Bitcoin attestation is attached to this PDF.","","Official company source:","https://publicity.businessportal.gr/company/182550901000","https://services.businessportal.gr/publicCertificateDownload/form","","Historical company-document extracts include incorporation,","representation, EORI assignment and Union OSS registration.","No current compliance, good-standing or independent audit verdict.","Private originals and customer identifiers are not attached."];const escape=s=>s.replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');let content='BT\n/F1 10 Tf\n40 800 Td\n14 TL\n';for(let i=0;i<lines.length;i++)content+=(i?'T*\n':'')+'('+escape(lines[i])+') Tj\n';content+='ET\n';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+content.length+' >>\nstream\n'+content+'endstream'];let output='%PDF-1.4\n';const offsets=[0];for(let i=0;i<objects.length;i++){offsets.push(output.length);output+=(i+1)+' 0 obj\n'+objects[i]+'\nendobj\n';}const start=output.length;output+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n';for(let i=1;i<offsets.length;i++)output+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';output+='trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF\n';return output;}

async function signedHttpEvidenceResponse(request,env,kind){
  if(request.method!=='GET')return new Response('GET required for this signed response profile',{status:405,headers:{...headers('text/plain; charset=utf-8'),Allow:'GET'}});
  if(!env.HTTP_SIGNATURE_JWK)return new Response(JSON.stringify({error:'http_signing_not_configured',meaning:'Use a separate Ed25519 private JWK in the new Worker encrypted secret HTTP_SIGNATURE_JWK. No existing signing keys are reused automatically.'}),{status:503,headers:headers('application/json; charset=utf-8')});
  try{
    const jwk=JSON.parse(env.HTTP_SIGNATURE_JWK);
    if(jwk.kty!=='OKP'||jwk.crv!=='Ed25519'||typeof jwk.x!=='string'||typeof jwk.d!=='string')throw new Error('Invalid key');
    const publicJwk={crv:'Ed25519',kty:'OKP',x:jwk.x};
    const enc=new TextEncoder();
    const thumbprint=base64url(new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(canonical(publicJwk)))));
    const url=new URL(request.url);
    const directory=kind==='directory';
    const contentType=directory?'application/http-message-signatures-directory+json':'application/json';
    const body=directory?JSON.stringify({keys:[{...publicJwk,kid:thumbprint}]}):JSON.stringify({format:'paragon-http-evidence/0.1',edition:EDITION,scope:'HTTP response signature example only, not source verification, bot registration or access authorization.',publicPayload:(await capsule(env)).payload});
    const contentHash=new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(body)));
    const contentDigest='sha-256=:'+btoa(String.fromCharCode(...contentHash))+':';
    const created=Math.floor(Date.now()/1000),expires=created+120;
    const components='("@status" "content-digest" "content-type" "@authority";req)';
    const params=components+';created='+created+';expires='+expires+';keyid="'+thumbprint+'";alg="ed25519"'+(directory?';tag="http-message-signatures-directory"':'');
    const base='"@status": 200\n"content-digest": '+contentDigest+'\n"content-type": '+contentType+'\n"@authority";req: '+url.host+'\n"@signature-params": '+params;
    const key=await crypto.subtle.importKey('jwk',jwk,{name:'Ed25519'},false,['sign']);
    const sig=new Uint8Array(await crypto.subtle.sign('Ed25519',key,enc.encode(base)));
    const verifyKey=await crypto.subtle.importKey('jwk',publicJwk,{name:'Ed25519'},false,['verify']);
    if(!await crypto.subtle.verify('Ed25519',verifyKey,sig,enc.encode(base)))throw new Error('Key mismatch');
    return new Response(body,{headers:{...headers(contentType),'Content-Digest':contentDigest,'Signature-Input':'sig1='+params,Signature:'sig1=:'+btoa(String.fromCharCode(...sig))+':'}});
  }catch(e){return new Response(JSON.stringify({error:'http_signing_failed',meaning:'No unsigned fallback served.'}),{status:503,headers:headers('application/json; charset=utf-8')});}
}


function nlwebListCandidate(request){
 const url=new URL(request.url);const query=url.searchParams.get('query')||'';const mode=url.searchParams.get('mode')||'list';const streaming=url.searchParams.get('streaming');
 const fail=(error,status)=>new Response(JSON.stringify({error,profile:'experimental-nonstreaming-list-only'}),{status,headers:headers('application/json; charset=utf-8')});
 if(!query.trim()||query.length>512)return fail('A query of 1..512 characters is required',400);
 if(mode!=='list')return fail('Only list mode is implemented; no LLM generation or summarization',422);
 if(streaming!=='false'&&streaming!=='0')return fail('This candidate requires streaming=false explicitly; SSE is not implemented',422);
 if(url.searchParams.has('prev')||url.searchParams.has('decontextualized_query'))return fail('Conversation context is not supported by this narrow candidate profile',422);
 const terms=query.toLocaleLowerCase('en').split(/[^\p{L}\p{N}]+/u).filter(Boolean).slice(0,32);
 const scored=RECORDS.map(record=>{const text=canonical(record).toLocaleLowerCase('en');const hits=terms.filter(t=>text.includes(t)).length;return {record,hits};}).filter(x=>x.hits>0).sort((a,b)=>b.hits-a.hits||a.record.id.localeCompare(b.record.id,'en')).slice(0,8);
 const results=scored.map(({record,hits})=>({url:new URL('/api/proof?id='+encodeURIComponent(record.id),url.origin).href,name:record.id,site:url.hostname,score:Math.round(100*hits/Math.max(1,terms.length)),description:String(record.claim||''),schema_object:{'@context':'https://schema.org','@type':'CreativeWork',name:record.id,description:String(record.claim||''),additionalProperty:[{name:'provenance',value:record.verification||'publisher_selected_reference'}]}}));
 return new Response(JSON.stringify({query_id:crypto.randomUUID(),results,profile:'NLWeb REST-inspired GET/list/nonstreaming candidate; not full NLWeb or MCP implementation',ranking:'Deterministic token overlap, not a reliability score, LLM assessment or independent authentication',source:'Manually curated dated public evidence records only'},null,2),{headers:headers('application/json; charset=utf-8')});
}

function headers(type){return {'Content-Type':type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, nofollow','Cache-Control':'no-store','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'none'; script-src 'self' 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self' https://alice.btc.calendar.opentimestamps.org https://bob.btc.calendar.opentimestamps.org https://blockstream.info; img-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"};}
export default {
  async fetch(request,env={}) {
    const url=new URL(request.url);
    if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405,headers:{...headers('text/plain; charset=utf-8'),Allow:'GET, HEAD'}});
    const head=request.method==='HEAD';
    if(url.pathname==='/ask'){if(env.ENABLE_EXPERIMENTAL_NLWEB_LIST!=='true')return new Response(JSON.stringify({error:'experimental_adapter_disabled',meaning:'This opt-in GET/list/nonstreaming candidate is not a full NLWeb service.'}),{status:503,headers:headers('application/json; charset=utf-8')});return nlwebListCandidate(request);}
    if(url.pathname==='/api/protocol-status')return new Response(head?null:JSON.stringify({edition:EDITION,nlweb:{profile:'GET-list-nonstreaming-candidate',enabled:env.ENABLE_EXPERIMENTAL_NLWEB_LIST==='true',fullConformance:false,mcp:false,llm:false},webBotAuth:{responseSigningCandidate:true,requestSignerSourceIncludedInResearchPackage:true,registered:false,incomingRequestVerifier:false},anp:{enabled:false,reason:'DID binding, authenticated description and conformance not completed'},ap2:{paymentsEnabled:false,fullMandateVerifier:false,localSignedJwtBindingInspectorOnly:true},tee:{enabled:false,reason:'No zero-cost attested hardware service provisioned'}},null,2),{headers:headers('application/json; charset=utf-8')});
    if(url.pathname==='/.well-known/http-message-signatures-directory')return signedHttpEvidenceResponse(request,env,'directory');
    if(url.pathname==='/api/http-signed-evidence')return signedHttpEvidenceResponse(request,env,'evidence');
    if(url.pathname==='/source/main.js')return new Response(head?null:SOURCE_MAIN,{headers:headers('application/javascript; charset=utf-8')});
    if(url.pathname==='/api/build-ingredients'){const files=[['main.js',SOURCE_MAIN],['ml-dsa.mjs',PQ_VENDOR],['qr.js',QR_VENDOR],['ots.js',OTS_VENDOR]];const ingredients=[];for(const [name,source]of files){const bytes=new TextEncoder().encode(source);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');ingredients.push({name,bytes:bytes.length,sha256:hash});}return new Response(head?null:JSON.stringify({format:'paragon-build-ingredients/0.1',edition:EDITION,ingredients,reproducibleBuildVerified:false,formalVerification:false,meaning:'Source and dependency integrity ingredients only. Not an independently reproduced build or formal proof. No automatic source synchronization.'},null,2),{headers:headers('application/json; charset=utf-8')});}
    if(url.pathname==='/public-evidence-summary.pdf')return new Response(head?null:publicSummaryPdf(),{headers:{...headers('application/pdf'),'Content-Disposition':'inline; filename=paragon-public-evidence-summary.pdf'}});
    if(url.pathname==='/vendor/ml-dsa.mjs')return new Response(head?null:PQ_VENDOR,{headers:headers('application/javascript; charset=utf-8')});
    if(url.pathname==='/vendor/qr.js')return new Response(head?null:QR_VENDOR,{headers:headers('application/javascript; charset=utf-8')});
    if(url.pathname==='/vendor/additional-licenses.txt')return new Response(head?null:ADDITIONAL_LICENSES,{headers:headers('text/plain; charset=utf-8')});
    if(url.pathname==='/vendor/ots.js')return new Response(head?null:OTS_VENDOR,{headers:headers('application/javascript; charset=utf-8')});
    if(url.pathname==='/vendor/ots-license.txt')return new Response(head?null:OTS_LICENSE,{headers:headers('text/plain; charset=utf-8')});
    if(url.pathname==='/robots.txt')return new Response(head?null:'User-agent: *\nDisallow: /\n',{headers:headers('text/plain; charset=utf-8')});
    if(url.pathname==='/health')return new Response(head?null:JSON.stringify({edition:EDITION,state:'untested_research_starter',outboundRequests:false,storage:false,signingConfigured:Boolean(env.CAPSULE_SIGNING_JWK),signatureVerification:'not_performed_by_health_endpoint'}),{headers:headers('application/json; charset=utf-8')});
    if(url.pathname==='/api/capabilities')return new Response(head?null:JSON.stringify({edition:EDITION,status:'unexecuted_research_code',routes:['/','/verifier.html','/api/capsule','/api/proof?id=historical-delivery-countries','/api/capabilities','/api/build-ingredients','/source/main.js','/public-evidence-summary.pdf','/vendor/ml-dsa.mjs','/vendor/qr.js','/vendor/ots.js','/vendor/ots-license.txt','/vendor/additional-licenses.txt','/robots.txt','/health'],includedCode:['offline-hash-verifier','ed25519-optional','merkle-inclusion','selective-record-envelope','local-edition-comparison','exact-timestamp-payload-export','browser-ots-submission-after-consent','browser-ots-upgrade-remote-explorer-verification','official-certificate-verification-route','browser-ml-dsa65-keygen-sign-verify','official-source-navigation-qr-generation','manual-private-purchase-records','private-signed-correction-notices','public-raw-carv1-export','source-dependency-hash-ingredients','optional-http-message-response-signatures-candidate','optional-signed-http-key-directory-candidate'],notImplemented:['ZK','FHE','PIR','TEE','full-node-timestamp-verification','formal-verification','verified-reproducible-build','company-registry-validation','crawler-notification','pdf-signature-validation','qr-authentication'],outboundRequests:false,persistentHistory:false}),{headers:headers('application/json; charset=utf-8')});
    if(url.pathname!=='/'&&url.pathname!=='/verifier.html'&&url.pathname!=='/api/capsule'&&url.pathname!=='/api/proof')return new Response(head?null:'Not found',{status:404,headers:headers('text/plain; charset=utf-8')});
    let c;
    try { c=await capsule(env); } catch (_) { return new Response(head?null:JSON.stringify({error:"capsule_unavailable",reason:"Signing configuration or capsule construction failed. No unsigned fallback is served when signing configuration fails."}),{status:503,headers:headers("application/json; charset=utf-8")}); }
    if(url.pathname==='/api/proof') {
      const id=url.searchParams.get('id');const proof=c.proofs.find(p=>p.record.id===id);
      if(!proof)return new Response(head?null:JSON.stringify({error:'record_not_found'}),{status:404,headers:headers('application/json; charset=utf-8')});
      return new Response(head?null:JSON.stringify({format:'paragon-selective-record/0.1',commitment:c.recordSet.commitment,authentication:c.recordSet.authentication,proof,limitations:['Membership under supplied root only. Not truth or independent identity.','Not zero knowledge. Sibling hashes may leak predictable records.']},null,2),{headers:headers('application/json; charset=utf-8')});
    }
    if(url.pathname==='/api/capsule')return new Response(head?null:JSON.stringify(c,null,2),{headers:headers('application/json; charset=utf-8')});
    const safe=JSON.stringify(c).replace(/</g,'\\u003c');
    return new Response(head?null:PAGE.replace('__CAPSULE__',safe),{headers:headers('text/html; charset=utf-8')});
  }
};
